use cudarc::{driver::{CudaContext,CudaFunction,CudaSlice,CudaStream,DevicePtr,LaunchConfig,PushKernelArg,sys},nvrtc::Ptx};
use std::{fs::{File,OpenOptions},io::{BufWriter,Write},path::PathBuf,sync::Arc};
fn emit(v:serde_json::Value){println!("D247_CONTROL {v}");std::io::stdout().flush().unwrap();}
fn vecraw(f:&mut BufWriter<File>,v:&[u32]){f.write_all(&(v.len()as u64).to_le_bytes()).unwrap();for x in v{f.write_all(&x.to_le_bytes()).unwrap();}}
fn source(id:u32,blocks:usize,n:usize)->Vec<u32>{
 const B:[u32;16]=[0,0x80000000,1,0x80000001,0x007fffff,0x00800000,0x3f800000,0xbf800000,0x7f800000,0xff800000,0x7fc01234,0xffc01234,0x7f801234,0xff801234,0x7f7fffff,0xffffffff];
 let len=17+blocks*n+19;let mut out:Vec<u32>=(0..len).map(|i|0xa5123456u32.wrapping_add(id.wrapping_mul(131)).wrapping_add((i as u32).wrapping_mul(17))).collect();
 for b in 0..blocks{for i in 0..n{out[17+b*n+i]=if i%3==0{(i as u32).wrapping_mul(0x85ebca6b)^id.wrapping_mul(0xc2b2ae35)^((b+1)as u32).wrapping_mul(0x9e3779b9)}else{B[(i+id as usize+b)%16]};}}out
}
fn poison(id:u32,phase:u32,len:usize)->Vec<u32>{(0..len).map(|i|0xcd000000^id.wrapping_mul(257)^phase.wrapping_mul(0x9e37)^(i as u32).wrapping_mul(13)).collect()}
fn launch(f:&CudaFunction,s:&Arc<CudaStream>,input:&CudaSlice<u32>,out:&mut CudaSlice<u32>,n:u32,threads:u32,blocks:u32){let base=17u32;unsafe{s.launch_builder(f).arg(input).arg(out).arg(&n).arg(&base).launch(LaunchConfig{grid_dim:(blocks,1,1),block_dim:(threads,1,1),shared_mem_bytes:n.max(1)*4}).unwrap();}}
fn graph_witness(g:&cudarc::driver::CudaGraph,threads:u32,blocks:u32,n:u32)->serde_json::Value{unsafe{
 let mut count=0;assert_eq!(sys::cuGraphGetNodes(g.cu_graph(),std::ptr::null_mut(),&mut count),sys::CUresult::CUDA_SUCCESS);assert_eq!(count,1);let mut nodes=vec![std::ptr::null_mut();count];assert_eq!(sys::cuGraphGetNodes(g.cu_graph(),nodes.as_mut_ptr(),&mut count),sys::CUresult::CUDA_SUCCESS);
 let mut kind=sys::CUgraphNodeType::CU_GRAPH_NODE_TYPE_KERNEL;assert_eq!(sys::cuGraphNodeGetType(nodes[0],&mut kind),sys::CUresult::CUDA_SUCCESS);assert_eq!(kind,sys::CUgraphNodeType::CU_GRAPH_NODE_TYPE_KERNEL);
 let mut p:sys::CUDA_KERNEL_NODE_PARAMS=std::mem::zeroed();assert_eq!(sys::cuGraphKernelNodeGetParams_v2(nodes[0],&mut p),sys::CUresult::CUDA_SUCCESS);assert_eq!([p.gridDimX,p.gridDimY,p.gridDimZ],[blocks,1,1]);assert_eq!([p.blockDimX,p.blockDimY,p.blockDimZ],[threads,1,1]);assert_eq!(p.sharedMemBytes,n.max(1)*4);
 let mut dims=Vec::new();for attr in [sys::CUfunction_attribute_enum::CU_FUNC_ATTRIBUTE_REQUIRED_CLUSTER_WIDTH,sys::CUfunction_attribute_enum::CU_FUNC_ATTRIBUTE_REQUIRED_CLUSTER_HEIGHT,sys::CUfunction_attribute_enum::CU_FUNC_ATTRIBUTE_REQUIRED_CLUSTER_DEPTH]{let mut value=0;assert_eq!(sys::cuFuncGetAttribute(&mut value,attr,p.func),sys::CUresult::CUDA_SUCCESS);dims.push(value);}assert_eq!(dims,[2,1,1]);
 serde_json::json!({"kernel_nodes":1,"grid":[blocks,1,1],"block":[threads,1,1],"dynamic_shared_per_block":p.sharedMemBytes,"captured_function_required_cluster_dimensions":dims})}}
fn main(){
 let dir=PathBuf::from(std::env::args().nth(1).unwrap());std::fs::create_dir(&dir).unwrap();let cases:Vec<serde_json::Value>=serde_json::from_str(include_str!("corpus.json")).unwrap();assert_eq!(cases.len(),132);
 let ctx=CudaContext::new(0).unwrap();assert_eq!(ctx.name().unwrap(),"NVIDIA GeForce RTX 5090");assert_eq!(ctx.compute_capability().unwrap(),(12,0));assert_eq!(ctx.attribute(sys::CUdevice_attribute::CU_DEVICE_ATTRIBUTE_CLUSTER_LAUNCH).unwrap(),1);let s=ctx.new_stream().unwrap();unsafe{ctx.disable_event_tracking()};let m=ctx.load_module(Ptx::from_src(include_str!("primitive.ptx"))).unwrap();let f=m.load_function("d246_cluster_transport").unwrap();assert_eq!(f.get_attribute(sys::CUfunction_attribute_enum::CU_FUNC_ATTRIBUTE_REQUIRED_CLUSTER_WIDTH).unwrap(),2);assert_eq!(f.local_size_bytes().unwrap(),0);
 let mut raw=BufWriter::new(OpenOptions::new().create_new(true).write(true).open(dir.join("raw.bin")).unwrap());raw.write_all(b"D247-CLUSTER-RAW1\0").unwrap();raw.write_all(&132u32.to_le_bytes()).unwrap();let mut metadata=Vec::new();let mut words=0u64;let mut launches=0u32;let mut changes=0u64;
 for (id,c)in cases.iter().enumerate(){assert_eq!(c["id"].as_u64().unwrap(),id as u64);let threads=c["threads"].as_u64().unwrap()as u32;let clusters=c["clusters"].as_u64().unwrap()as u32;let n=c["words_per_block"].as_u64().unwrap()as u32;let blocks=clusters*2;let initial=source(id as u32,blocks as usize,n as usize);let len=initial.len();let input=s.clone_htod(&initial).unwrap();let mut out=s.clone_htod(&poison(id as u32,0,len)).unwrap();s.synchronize().unwrap();let(ap,ag)=input.device_ptr(&s);let(bp,bg)=out.device_ptr(&s);assert!(ap+len as u64*4<=bp||bp+len as u64*4<=ap);drop(ag);drop(bg);
  // Capture and inspect the original graph before the first executed kernel.
  s.begin_capture(sys::CUstreamCaptureMode::CU_STREAM_CAPTURE_MODE_THREAD_LOCAL).unwrap();launch(&f,&s,&input,&mut out,n,threads,blocks);let g=s.end_capture(sys::CUgraphInstantiate_flags::CUDA_GRAPH_INSTANTIATE_FLAG_AUTO_FREE_ON_LAUNCH).unwrap().unwrap();let witness=graph_witness(&g,threads,blocks,n);
  for x in [id as u32,threads,clusters,n,len as u32]{raw.write_all(&x.to_le_bytes()).unwrap();}vecraw(&mut raw,&initial);words+=len as u64;
  for phase in 0..5u32{let seed=poison(id as u32,phase,len);s.memcpy_htod(&seed,&mut out).unwrap();let actual_before=s.clone_dtoh(&out).unwrap();assert_eq!(actual_before,seed);if phase==0{launch(&f,&s,&input,&mut out,n,threads,blocks);}else{g.launch().unwrap();}s.synchronize().unwrap();launches+=1;
   let actual=s.clone_dtoh(&out).unwrap();let post=s.clone_dtoh(&input).unwrap();assert_eq!(post,initial,"immutable{id}/{phase}");let mut expected=seed.clone();for b in 0..blocks as usize{for i in 0..n as usize{expected[17+b*n as usize+i]=initial[17+(b^1)*n as usize+i];}}assert_eq!(actual,expected,"fullpeertransport{id}/{phase}");let changed=actual.iter().zip(seed.iter()).filter(|(a,b)|a!=b).count()as u64;if n>0{assert!(changed>0);}changes+=changed;
   raw.write_all(&phase.to_le_bytes()).unwrap();for v in [&actual_before,&actual,&post]{vecraw(&mut raw,v);words+=v.len()as u64;}
  }
  raw.flush().unwrap();metadata.push(serde_json::json!({"id":id,"descriptor":c,"physical_words_each":len,"actual_device_regions":[[ap,len as u64*4],[bp,len as u64*4]],"graph":witness,"eager_launches":1,"graph_replays":4,"whole_outputs_inputs_guards_exact":true}));emit(serde_json::json!({"stage":"case","id":id,"threads":threads,"clusters":clusters,"words_per_block":n,"eager":1,"graph_replays":4,"exact":true}));drop(g);drop(out);drop(input);ctx.check_err().unwrap();
 }
 assert_eq!(launches,660);assert!(changes>0);raw.flush().unwrap();raw.get_ref().sync_all().unwrap();drop(raw);let mut file=OpenOptions::new().create_new(true).write(true).open(dir.join("metadata.json")).unwrap();file.write_all(serde_json::to_string_pretty(&serde_json::json!({"cases":metadata,"case_count":132,"kernel_launches":launches,"capture_kernel_nodes":132,"represented_raw_words":words,"nonvacuous_output_changes":changes,"solver_or_speed_samples":0})).unwrap().as_bytes()).unwrap();file.sync_all().unwrap();drop(file);drop(f);drop(m);drop(s);ctx.check_err().unwrap();drop(ctx);emit(serde_json::json!({"stage":"complete","cases":132,"kernel_launches":660,"represented_raw_words":words,"nonvacuous_output_changes":changes,"solver_or_speed_samples":0,"candidate_accepted":false}));
}
